  nth_error (r_st (pr Σ c)) i = Some (CkQuar n) -> nth_error (r_st (pr Σ c')) i' = Some (CkQuar n') ->
  p_abeg (l_SB (lay Σ)) c i + rz_size n - 16 = p_abeg (l_SB (lay Σ)) c' i' + rz_size n' - 16 -> c = c' /\ i = i'.
Proof.
